def transform(grid):
    h, w = len(grid), len(grid[0])

    # The separator color forms complete rows and columns.
    sep = next(
        grid[r][0] for r in range(h)
        if all(v == grid[r][0] for v in grid[r]) and grid[r][0] != 0
    )

    # Find the non-marker motif in one of the 4x4 compartments.
    motif = None
    for br in range(0, h, 5):
        for bc in range(5, w, 5):
            vals = [grid[br + r][bc + c] for r in range(4) for c in range(4)]
            colors = {v for v in vals if v != 0 and v != sep}
            if colors:
                color = next(iter(colors))
                motif = [[grid[br + r][bc + c] == color for c in range(4)]
                         for r in range(4)]
                break
        if motif:
            break

    out = [[sep if r % 5 == 4 or c % 5 == 4 else 0 for c in range(w)]
           for r in range(h)]
    for br in range(0, h, 5):
        marker = next((grid[br + 1][c] for c in range(4)
                       if grid[br + 1][c] not in (0, sep)), 0)
        for bc in range(0, w, 5):
            for r in range(4):
                for c in range(4):
                    if motif and motif[r][c]:
                        out[br + r][bc + c] = marker
    return out
